let reassign = (cb: any) => {
  let { value, ...desc } = originalDescriptor || {
    configurable: true,
    writable: true,
  }
  if (accessType !== 'value') {
    delete desc.writable // getter/setter can't have writable attribute at all
  }
  ;(desc as PropertyDescriptor)[accessType] = cb
  define(obj, accessName, desc)
}
let restore = () => {
  if (objDescriptor) {
    // Property was an own property, restore it
    define(obj, accessName, originalDescriptor)
  } else if (originalDescriptor) {
    // Property was inherited, just delete our spy to reveal the inherited one
    delete (obj as any)[accessName]
  } else {
    // No original descriptor at all, reassign original
    reassign(original)
  }
}

